// OutputsOfBoms is the by-products of the BoMs, by BoM and sort order.
func (q *Queries) OutputsOfBoms(ctx context.Context, bomIds []int64) ([]ManufacturingBomOutput, error) {
	rows, err := q.db.Query(ctx, outputsOfBoms, bomIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ManufacturingBomOutput
	for rows.Next() {
		var i ManufacturingBomOutput
		if err := rows.Scan(
			&i.ID,
			&i.BomID,
			&i.VariantID,
			&i.Quantity,
			&i.CostShare,
			&i.SortOrder,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

