const productionConsumption = `-- name: ProductionConsumption :many
SELECT l.production_id, c.id AS component_id, c.variant_id, c.sku, c.product_name, c.unit, c.sort_order,
       COALESCE(ll.lot_id, 0)::bigint AS lot_id, COALESCE(ll.lot_number, '')::text AS lot_number,
       COALESCE(ll.consumed, l.consumed)::numeric(14, 3) AS consumed
FROM manufacturing.production_lines l
JOIN manufacturing.order_components c ON c.id = l.component_id
LEFT JOIN manufacturing.production_line_lots ll ON ll.production_id = l.production_id AND ll.component_id = l.component_id
WHERE l.production_id = ANY($1::bigint[])
ORDER BY c.sort_order, c.id, l.production_id, ll.lot_number, ll.location_id
`

type ProductionConsumptionRow struct {
	ProductionID int64
	ComponentID  int64
	VariantID    int32
	Sku          string
	ProductName  string
	Unit         string
	SortOrder    int32
	LotID        int64
	LotNumber    string
	Consumed     pgtype.Numeric
}

// ProductionConsumption is what each production consumed per component line
// (scrap left out): the line's variant, its consumed total, and per lot taken
// what it consumed of it (lot_id 0 and the line's total when it took no lot).
func (q *Queries) ProductionConsumption(ctx context.Context, productionIds []int64) ([]ProductionConsumptionRow, error) {
	rows, err := q.db.Query(ctx, productionConsumption, productionIds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ProductionConsumptionRow
	for rows.Next() {
		var i ProductionConsumptionRow
		if err := rows.Scan(
			&i.ProductionID,
			&i.ComponentID,
			&i.VariantID,
			&i.Sku,
			&i.ProductName,
			&i.Unit,
			&i.SortOrder,
			&i.LotID,
			&i.LotNumber,
			&i.Consumed,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

